18	// on-disk layout inside the data directory:
19	//
20	//	data.json    – the committed state (JSON envelope, atomically replaced)
21	//	data.json.tmp– staging file for the next commit (rename(2) target)
22	//	lock         – flock file serializing concurrent processes
23	//
24	// The envelope carries an explicit format version: files written by an
25	// incompatible future build are refused rather than silently migrated or
26	// overwritten.
27	const (
28		dirDataFile = "data.json"
29		dirTmpFile  = "data.json.tmp"
30		dirLockFile = "lock"
31	
32		// FormatVersion is the on-disk format this build writes and accepts.
33		FormatVersion = 1
34	)
35	
36	// envelope is the persisted state container.
37	//
38	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
39	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
40	// decides what a committed circuit record may look like. UnmarshalJSON first
41	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
42	// object key anywhere encoding/json would otherwise keep the last value. At
43	// the envelope's top level that comparison is case-insensitive for the five
44	// known fields (format/circuits/setups/jobs/artifacts): a second spelling
45	// that differs only in ASCII letter case — including one JSON-escaped — names
46	// the same field and corrupts the read instead of overriding it. A spelling
47	// that Unicode case-folds onto one of those fields yet is not an ASCII case
48	// variant ("circuitſ" with U+017F long s, directly written or ſ-escaped)
49	// is likewise corruption even when it is the only spelling present, since
50	// encoding/json's own tag matching would fill the field from it; a later
51	// "circuitſ": [] must never read the circuits as empty and drop them on the
52	// next commit.
53	type envelope struct {
54		Format    int               `json:"format"`
55		Circuits  []persistCircuit  `json:"circuits"`
56		Setups    []persistSetup    `json:"setups"`
57		Jobs      []persistJob      `json:"jobs"`
58		Artifacts []persistArtifact `json:"artifacts,omitempty"`
59	}
60	
61	// envelopeWire is the decoding-only shape: circuit records arrive raw so
62	// their own strict decoder can require every field explicitly.
63	type envelopeWire struct {
64		Format    int               `json:"format"`
65		Circuits  []json.RawMessage `json:"circuits"`
66		Setups    []persistSetup    `json:"setups"`
67		Jobs      []persistJob      `json:"jobs"`
68		Artifacts []persistArtifact `json:"artifacts,omitempty"`
69	}
70	
71	func (e *envelope) UnmarshalJSON(raw []byte) error {
72		// Reject repeated keys before decoding: encoding/json silently keeps the
73		// last value of a duplicate. The walk is layered so a repeated field is
74		// attributed to the record it belongs to (a duplicate "frozen" inside
75		// circuit #3, not a generic envelope complaint).
76		if err := scanEnvelopeDuplicates(raw); err != nil {
77			return err
78		}
79		var wire envelopeWire
80		if err := json.Unmarshal(raw, &wire); err != nil {
81			var se StoreError
82			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
83				return err // an inner record decoder already named the problem
84			}
85			return corruptf("data file envelope is not valid JSON: %v", err)
86		}
87		e.Format = wire.Format
88		e.Setups = wire.Setups
89		e.Jobs = wire.Jobs
90		e.Artifacts = wire.Artifacts
91		if wire.Circuits == nil {
92			e.Circuits = nil
93		} else {
94			e.Circuits = make([]persistCircuit, len(wire.Circuits))
95		}
96		for i, craw := range wire.Circuits {
97			var record persistCircuit
98			if err := json.Unmarshal(craw, &record); err != nil {
99				var se StoreError
100				if errors.As(err, &se) {
101					// Re-tag as one corruption error carrying the record index,
102					// so the detail survives errors.As unwrapping in loadLocked.
103					return StoreError{Kind: ErrDataCorrupt.Kind,
104						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
105				}
106				return corruptf("circuit record #%d: %v", i+1, err)
107			}
108			e.Circuits[i] = record
109		}
110		return nil
111	}
112	
113	// envelopeTopFields are the five fields an envelope may carry. Their
114	// canonical (standard lowercase) spellings are the wire tags on envelope and
115	// envelopeWire; JSON keys are tokenized after unescaping.
116	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
117	
118	// canonicalEnvelopeField reports the standard lowercase name of one of the
119	// five envelope fields when key names it under any ASCII letter-case spelling
120	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
121	// tokenizer, so an escaped spelling of any such form lands here too. A
122	// non-canonical key (different length or a mismatching byte, including
123	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
124	func canonicalEnvelopeField(key string) string {
125		for _, field := range envelopeTopFields {
126			if len(key) != len(field) {
127				continue
128			}
129			i := 0
130			for i < len(key) {
131				c := key[i]
132				if c >= 'A' && c <= 'Z' {
133					c += 'a' - 'A'
134				}
135				if c != field[i] {
136					break
137				}
138				i++
139			}
140			if i == len(field) {
141				return field
142			}
143		}
144		return ""
145	}
146	
147	// envelopeFieldLookalike reports the standard lowercase name of one of the
148	// five envelope fields when key names it under a spelling encoding/json's
149	// struct-tag matching would fold onto the field but which is not an accepted
150	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
151	// matching folds with the Unicode simple case-folding rules
152	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
153	// the JSON escape u017f — keys arrive here already unescaped) names the
154	// circuits field exactly like "circuits", even standing alone. Such a
155	// lookalike is damage whatever its value: a later "circuitſ": [] would
156	// otherwise override a populated circuits array through last-value-wins and
157	// the records would vanish on the next commit. A key that does not fold onto
158	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
159	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
160	// the ordinary unknown-member handling.
161	func envelopeFieldLookalike(key string) string {
162		if canonicalEnvelopeField(key) != "" {
163			return "" // an accepted ASCII spelling, not a lookalike
164		}
165		for _, field := range envelopeTopFields {
166			if strings.EqualFold(key, field) {
167				return field
168			}
169		}
170		return ""
171	}
172	
173	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
174	// repeated object key. The five known top-level fields are identified case-
175	// insensitively: two spellings that differ only in ASCII letter case (both
176	// keys already JSON-unescaped at this point) are the same field, in whatever
177	// order they appear and whether or not their values agree, so a later
178	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
179	// json's last-value-wins struct matching. Such a pair is reported as a
180	// duplicated top-level field named by its standard lowercase spelling.
181	//
182	// A non-ASCII spelling that folds onto a known field but is not an ASCII case
183	// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
184	// directly written or ſ-escaped) is rejected outright as data corruption:
185	// encoding/json would match it onto the field, so ignoring it as unknown
186	// could let its value replace the real one (an empty array hiding every
187	// record), and accepting it would let the records vanish on the next commit.
188	// The rule holds for the lookalike appearing alone — value a legal record, an
189	// empty array or null alike — and for it appearing beside the canonical
190	// spelling or an ASCII case variant, in either order and whether the values
191	// agree. The error names both the standard field and the actual spelling.
192	//
193	// Circuit records are scanned one level deep only — their top-level fields
194	// are checked here (with the record's 1-based index reported), while values
195	// such as the constraint definition are skipped and left to their own strict
196	// decoders. Every other envelope member is scanned recursively so a
197	// duplicated key anywhere in committed data fails the read instead of
198	// silently resolving to its last value.
199	func scanEnvelopeDuplicates(raw []byte) error {
200		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
201		dec.UseNumber()
202		open, err := dec.Token()
203		if err != nil || open != json.Delim('{') {
204			return corruptf("data file envelope must be a JSON object")
205		}
206		// Exact spellings retain the pre-existing check for unknown keys;
207		// canonical names remember a known field's first occurrence regardless
208		// of the case it was written in.
209		seenTop := make(map[string]bool)
210		seenCanonical := make(map[string]bool)
211		for dec.More() {
212			keyTok, err := dec.Token()
213			if err != nil {
214				return corruptf("data file envelope is not valid JSON: %v", err)
215			}
216			key, ok := keyTok.(string)
217			if !ok {
218				return corruptf("data file envelope is not valid JSON")
219			}
220			// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
221			// matching would read as a known field ("circuitſ" with long s,
222			// directly written or ſ-escaped) before anything else. It is damage
223			// even on its own and whatever its value — a legal record, an empty
224			// array or null — and whether it precedes or follows the canonical or
225			// an ASCII case-variant spelling: the read may neither ignore it as an
226			// unknown member nor choose one of the values and carry on.
227			if canonical := envelopeFieldLookalike(key); canonical != "" {
228				return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
229					canonical, key)
230			}
231			if canonical := canonicalEnvelopeField(key); canonical != "" {
232				if seenCanonical[canonical] {
233					if key == canonical {
234						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
235					}
236					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
237						canonical, key)
238				}
239				seenCanonical[canonical] = true
240				if canonical == "circuits" {
241					if err := scanCircuitArrayDuplicates(dec); err != nil {
242						return err
243					}
244					continue
245				}
246				if canonical == "jobs" {
247					if err := scanJobArrayDuplicates(dec); err != nil {
248						return err
249					}
250					continue
251				}
252				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
253					return err
254				}
255				continue
256			}
257			if seenTop[key] {
258				return corruptf("data file envelope contains duplicate field %q", key)
259			}
260			seenTop[key] = true
261			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
262				return err
263			}
264		}
265		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
266			return corruptf("data file envelope is not valid JSON")
267		}
268		if _, err := dec.Token(); err != io.EOF {
269			return corruptf("data file envelope is not valid JSON: trailing data after the object")
270		}
271		return nil
272	}
273	
274	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
275	// opening bracket and checks only each record's own top-level keys. The
276	// enclosing key may carry any case spelling, but the field it names is the
277	// canonical "circuits". A null array stays the pre-existing "no records"
278	// reading.
279	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
280		tok, err := dec.Token()
281		if err != nil {
282			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
283		}
284		if tok == nil { // null: json.Unmarshal would produce no records
285			return nil
286		}
287		if tok != json.Delim('[') {
288			return corruptf("data file envelope field \"circuits\" must be an array")
289		}
290		index := 0
291		for dec.More() {
292			index++
293			what := fmt.Sprintf("circuit record #%d", index)
294			open, err := dec.Token()
295			if err != nil {
296				return corruptf("%s is not valid JSON: %v", what, err)
297			}
298			if open == nil {
299				return corruptf("%s must be a JSON object, not null", what)
300			}
301			if open != json.Delim('{') {
302				return corruptf("%s must be a JSON object", what)
303			}
304			seen := make(map[string]bool)
305			for dec.More() {
306				keyTok, err := dec.Token()
307				if err != nil {
308					return corruptf("%s is not valid JSON: %v", what, err)
309				}
310				key, ok := keyTok.(string)
311				if !ok {
312					return corruptf("%s is not valid JSON", what)
313				}
314				if seen[key] {
315					return corruptf("%s contains duplicate field %q", what, key)
316				}
317				seen[key] = true
318				// Skip the whole value without descending: nested objects
319				// (definition) own their own strict duplicate checks.
320				var skip json.RawMessage
321				if err := dec.Decode(&skip); err != nil {
322					return corruptf("%s is not valid JSON: %v", what, err)
323				}
324			}
325			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
326				return corruptf("%s is not valid JSON", what)
327			}
328		}
329		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
330			return corruptf("data file envelope field \"circuits\" is not valid JSON")
331		}
332		return nil
333	}
334	
335	// scanJobArrayDuplicates consumes one "jobs" value positioned at its opening
336	// bracket. It is the jobs-array counterpart of scanCircuitArrayDuplicates and
337	// exists so a structural problem inside one job is attributed to that job — by
338	// its id when the id is a legible string, else by its 1-based position —
339	// rather than to an opaque "jobs" element index.
340	//
341	// Besides an exact repeated member key (compared after JSON unescaping, as for
342	// every other record), it enforces the pinned-version uniqueness rule here,
343	// before any value is decoded — the same rejectAmbiguousJobVersion rule the
344	// single-record decode applies, so both readings agree on which spellings
345	// name the version field and on the refusal message. Catching it here —
346	// rather than only in the record decoder — also covers two byte-identical
347	// "version" keys, which the record's strict member walk would otherwise
348	// reject without the id in hand. The verdict is deferred to the end of each
349	// record solely so a version written before the id still names the job; every
350	// token is consumed regardless. Nested member values keep the ordinary
351	// recursive duplicate scan. A null array stays the pre-existing "no jobs"
352	// reading.
353	func scanJobArrayDuplicates(dec *json.Decoder) error {
354		tok, err := dec.Token()
355		if err != nil {
356			return corruptf("data file envelope field \"jobs\" is not valid JSON: %v", err)
357		}
358		if tok == nil { // null: json.Unmarshal would produce no jobs
359			return nil
360		}
361		if tok != json.Delim('[') {
362			return corruptf("data file envelope field \"jobs\" must be an array")
363		}
364		index := 0
365		for dec.More() {
366			index++
367			positional := fmt.Sprintf("job record #%d", index)
368			open, err := dec.Token()
369			if err != nil {
370				return corruptf("%s is not valid JSON: %v", positional, err)
371			}
372			if open == nil {
373				return corruptf("%s must be a JSON object, not null", positional)
374			}
375			if open != json.Delim('{') {
376				return corruptf("%s must be a JSON object", positional)
377			}
378			var (
379				id         string
380				seenExact  = make(map[string]bool)
381				dupKey     string
382				memberKeys []string
383				nestedErr  error
384			)
385			for dec.More() {
386				keyTok, err := dec.Token()
387				if err != nil {
388					return corruptf("%s is not valid JSON: %v", positional, err)
389				}
390				key, ok := keyTok.(string)
391				if !ok {
392					return corruptf("%s is not valid JSON", positional)
393				}
394				// Consume the whole value first; judgments below use only the key
395				// (and, for id, the already-captured bytes). Job members are
396				// scalars, but an unknown member may carry an object/array whose
397				// own duplicate keys must still fail the read.
398				var value json.RawMessage
399				if err := dec.Decode(&value); err != nil {
400					return corruptf("%s is not valid JSON: %v", positional, err)
401				}
402				if key == "id" {
403					if idVal, ierr := storedRecordShape.string(value, positional+` field "id"`); ierr == nil {
404						id = idVal
405					}
406				}
407				memberKeys = append(memberKeys, key)
408				if seenExact[key] && dupKey == "" {
409					dupKey = key
410				}
411				seenExact[key] = true
412				trimmed := bytes.TrimSpace(value)
413				if nestedErr == nil && len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[') {
414					nd := json.NewDecoder(bytes.NewReader(trimmed))
415					nestedErr = skipValueWithDupKeys(nd, positional+" field "+strconv.Quote(key))
416				}
417			}
418			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
419				return corruptf("%s is not valid JSON", positional)
420			}
421			what := positional
422			if id != "" {
423				what = fmt.Sprintf("stored job record %q", id)
424			}
425			// A repeated version spelling is the pinned-version ambiguity and gets
426			// the specific message, including when both keys are byte-identical.
427			if err := rejectAmbiguousJobVersion(what, memberKeys); err != nil {
428				return err
429			}
430			if dupKey != "" {
431				return corruptf("%s contains duplicate field %q", what, dupKey)
432			}
433			if nestedErr != nil {
434				return nestedErr
435			}
436		}
437		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
438			return corruptf("data file envelope field \"jobs\" is not valid JSON")
439		}
440		return nil
441	}
442	
443	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
444	// recursively rejecting duplicate object keys.
445	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
446		tok, err := dec.Token()
447		if err != nil {
448			return corruptf("%s is not valid JSON: %v", what, err)
449		}
450		delim, ok := tok.(json.Delim)
451		if !ok {
452			return nil // scalar (including null)
453		}
454		switch delim {
455		case '{':
456			seen := make(map[string]bool)
457			for dec.More() {
458				keyTok, err := dec.Token()
459				if err != nil {
460					return corruptf("%s is not valid JSON: %v", what, err)
461				}
462				key, ok := keyTok.(string)
463				if !ok {
464					return corruptf("%s is not valid JSON", what)
465				}
466				if seen[key] {
467					return corruptf("%s contains duplicate field %q", what, key)
468				}
469				seen[key] = true
470				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
471					return err
472				}
473			}
474			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
475				return corruptf("%s is not valid JSON", what)
476			}
477		case '[':
478			index := 0
479			for dec.More() {
480				index++
481				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
482					return err
483				}
484			}
485			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
486				return corruptf("%s is not valid JSON", what)
487			}
488		}
489		return nil
490	}
