492	type persistTerm struct {
493		Wire  int    `json:"wire"`
494		Coeff string `json:"coeff"`
495	}
496	
497	type persistConstraint struct {
498		A []persistTerm `json:"a"`
499		B []persistTerm `json:"b"`
500		C []persistTerm `json:"c"`
501	}
502	
503	// persistDefinition is the canonical, already-validated constraint set bound
504	// to one circuit version. The public/private partition is owned by the
505	// circuit record and is deliberately not duplicated here, so it can never
506	// drift from the declared counts.
507	type persistDefinition struct {
508		Modulus     string              `json:"modulus"`
509		Constraints []persistConstraint `json:"constraints"`
510	}
511	
512	// persistArtifact is a compiled artifact: the version's identity and
513	// constraint count bound to its recomputable SHA-256 hash.
514	type persistArtifact struct {
515		Name        string `json:"name"`
516		Version     int    `json:"version"`
517		Modulus     int64  `json:"modulus"`
518		Constraints int    `json:"constraints"`
519		Hash        string `json:"hash"`
520	}
521	
522	type persistCircuit struct {
523		Name          string             `json:"name"`
524		Version       int                `json:"version"`
525		Constraints   int                `json:"constraints"`
526		PublicInputs  int                `json:"public_inputs"`
527		PrivateInputs int                `json:"private_inputs"`
528		Frozen        bool               `json:"frozen"`
529		Description   string             `json:"description"`
530		Definition    *persistDefinition `json:"definition,omitempty"`
531	}
532	
533	// Strict decoding of committed circuit records.
534	//
535	// A circuit record in data.json must name each of name, version, constraints,
536	// public_inputs, private_inputs, frozen and description exactly once, with
537	// the exact JSON type the writer emits (string / integer / integer / integer
538	// / integer / boolean / string). A missing key, a null, a wrong type or a
539	// repeated key is data corruption and refuses the whole directory read: a
540	// missing or null frozen flag must not silently read as false (turning a
541	// frozen version back into an editable draft), and a repeated key must not
542	// resolve to its last value. An explicit 0, false or "" is an ordinary value
543	// and stays legal. The definition member remains the one optional field: it
544	// may be absent or null (the legacy counts-only state); when present it goes
545	// through the strict persistDefinition decoder.
546	//
547	// The name field carries one rule beyond shape: its raw JSON string token
548	// must denote its value exactly — valid UTF-8 in the literal portions and no
549	// unpaired \uXXXX surrogate escapes (checkStoredNameEncoding). Both damage
550	// shapes decode to U+FFFD replacement characters under encoding/json, which
551	// would rename the circuit on read; they are data corruption, and the whole
552	// directory read is refused. Only the name is judged this way; every other
553	// field keeps the ordinary decoding rules.
554	//
555	// Only shape is judged here. The domain rules (non-blank name, positive
556	// version and constraint count, non-negative input counts) keep being
557	// re-checked by validateEnvelope.
558	
559	var persistCircuitFields = []string{
560		"name", "version", "constraints", "public_inputs", "private_inputs",
561		"frozen", "description", "definition",
562	}
563	
564	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
565	// tagged for committed data: every structural failure in a stored circuit
566	// record is data corruption, never a bad request.
567	var storedRecordShape = jsonShape{fail: corruptf}
568	
569	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
570		const what = "stored circuit record"
571		if string(bytes.TrimSpace(raw)) == "null" {
572			return corruptf("%s must be a JSON object, not null", what)
573		}
574		members, err := strictCircuitObject(raw, what)
575		if err != nil {
576			return err
577		}
578	
579		var out persistCircuit
580	
581		requireString := func(key string, dst *string) error {
582			r, err := storedRecordShape.require(members, key, what)
583			if err != nil {
584				return err
585			}
586			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
587			if err != nil {
588				return err
589			}
590			*dst = v
591			return nil
592		}
593		requireInt := func(key string, dst *int) error {
594			r, err := storedRecordShape.require(members, key, what)
595			if err != nil {
596				return err
597			}
598			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
599			if err != nil {
600				return err
601			}
602			*dst = v
603			return nil
604		}
605	
606		if err := requireString("name", &out.Name); err != nil {
607			return err
608		}
609		// The name is the version's identity and must read back as the exact
610		// value that was committed. encoding/json silently rewrites both invalid
611		// UTF-8 bytes and unpaired \uXXXX surrogate escapes to U+FFFD, so the
612		// decoded string alone cannot tell a damaged name apart from one that
613		// legitimately contains "�". Judge the raw JSON token instead.
614		if err := checkStoredNameEncoding(members["name"], what+` field "name"`); err != nil {
615			return err
616		}
617		if err := requireInt("version", &out.Version); err != nil {
618			return err
619		}
620		if err := requireInt("constraints", &out.Constraints); err != nil {
621			return err
622		}
623		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
624			return err
625		}
626		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
627			return err
628		}
629		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
630		if err != nil {
631			return err
632		}
633		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
634		if err != nil {
635			return err
636		}
637		if err := requireString("description", &out.Description); err != nil {
638			return err
639		}
640	
641		// definition is the only optional member: absent or null both mean the
642		// counts-only legacy state.
643		if defRaw, present := members["definition"]; present {
644			if string(bytes.TrimSpace(defRaw)) != "null" {
645				var def persistDefinition
646				if err := json.Unmarshal(defRaw, &def); err != nil {
647					var se StoreError
648					if errors.As(err, &se) {
649						return err // already reported as data corruption
650					}
651					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
652				}
653				out.Definition = &def
654			}
655		}
656	
657		*c = out
658		return nil
659	}
