667	// checkStoredNameEncoding enforces the circuit-name identity rule on the raw
668	// JSON string token of a committed circuit record's name field. The string
669	// has already been decoded by the strict member read, so the token is known
670	// to be one complete, well-formed JSON string; this walk judges only what
671	// that decode silently repairs:
672	//
673	//   - invalid UTF-8 bytes in the literal (unescaped) portions — a lone
674	//     continuation byte, a truncated multi-byte character, an overlong
675	//     form — which encoding/json rewrites to U+FFFD, and
676	//   - \uXXXX escapes forming an unpaired surrogate — a high surrogate not
677	//     immediately followed by its low-surrogate escape, or a low surrogate
678	//     standing alone — which are rewritten to U+FFFD the same way.
679	//
680	// Both would make the record read back under a different name than the bytes
681	// on disk carry, so the record is data corruption rather than a circuit
682	// named with a replacement character it never had. A legal surrogate pair
683	// decodes to its astral character, an actually committed "�" (written
684	// directly or as a U+FFFD escape) is an ordinary name, and the literal six
685	// characters "\uD800" — written with an escaped backslash — carry no escape
686	// at all: all three keep their exact value. Only the name field is judged
687	// here; every other field keeps the ordinary decoding rules.
688	func checkStoredNameEncoding(raw json.RawMessage, what string) error {
689		token := bytes.TrimSpace(raw)
690		// The token is a complete JSON string (the strict string read above
691		// succeeded), so every escape is well-formed and the walk stays in
692		// bounds; only the replacement-prone content is judged.
693		for i := 1; i < len(token)-1; {
694			c := token[i]
695			if c == '\\' {
696				if token[i+1] != 'u' {
697					i += 2 // a simple escape: \" \\ \/ \b \f \n \r \t
698					continue
699				}
700				code, _ := strconv.ParseUint(string(token[i+2:i+6]), 16, 32)
701				switch {
702				case code >= 0xD800 && code <= 0xDBFF:
703					// A high surrogate is whole only when its low-surrogate
704					// escape follows immediately.
705					if i+12 <= len(token) && token[i+6] == '\\' && token[i+7] == 'u' {
706						lo, _ := strconv.ParseUint(string(token[i+8:i+12]), 16, 32)
707						if lo >= 0xDC00 && lo <= 0xDFFF {
708							i += 12
709							continue
710						}
711					}
712					return corruptf("%s contains an unpaired high surrogate escape (\\u%04X); the committed name would not read back unchanged", what, code)
713				case code >= 0xDC00 && code <= 0xDFFF:
714					return corruptf("%s contains an unpaired low surrogate escape (\\u%04X); the committed name would not read back unchanged", what, code)
715				}
716				i += 6
717				continue
718			}
719			if c < utf8.RuneSelf {
720				i++
721				continue
722			}
723			r, size := utf8.DecodeRune(token[i:])
724			if r == utf8.RuneError && size == 1 {
725				return corruptf("%s contains invalid UTF-8 bytes; the committed name would not read back unchanged", what)
726			}
727			i += size
728		}
729		return nil
730	}
