732	// strictObjectMembers decodes one committed record's own member map,
733	// demanding a JSON object without repeated keys. A non-nil allowed list
734	// restricts which keys may appear; nil allows any key. It scans only the
735	// record's own level: the envelope scanner already attributes a duplicated
736	// top-level key to this record, and nested values such as the constraint
737	// definition own their (more precise) strict decoders. Keys are compared
738	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
739	// still a duplicate, even when both values are identical.
740	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
741		trimmed := bytes.TrimSpace(raw)
742		if len(trimmed) == 0 || trimmed[0] != '{' {
743			return nil, corruptf("%s must be a JSON object", what)
744		}
745		dec := json.NewDecoder(bytes.NewReader(trimmed))
746		dec.UseNumber()
747		open, err := dec.Token()
748		if err != nil || open != json.Delim('{') {
749			return nil, corruptf("%s must be a JSON object", what)
750		}
751		var allowed map[string]bool
752		if allowedFields != nil {
753			allowed = make(map[string]bool, len(allowedFields))
754			for _, f := range allowedFields {
755				allowed[f] = true
756			}
757		}
758		members := make(map[string]json.RawMessage)
759		for dec.More() {
760			keyTok, err := dec.Token()
761			if err != nil {
762				return nil, corruptf("%s is not valid JSON: %v", what, err)
763			}
764			key, ok := keyTok.(string)
765			if !ok {
766				return nil, corruptf("%s is not valid JSON", what)
767			}
768			if allowed != nil && !allowed[key] {
769				return nil, corruptf("%s has unknown field %q", what, key)
770			}
771			if _, repeated := members[key]; repeated {
772				return nil, corruptf("%s contains duplicate field %q", what, key)
773			}
774			var value json.RawMessage
775			if err := dec.Decode(&value); err != nil {
776				return nil, corruptf("%s is not valid JSON: %v", what, err)
777			}
778			members[key] = value
779		}
780		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
781			return nil, corruptf("%s is not valid JSON", what)
782		}
783		if _, err := dec.Token(); err != io.EOF {
784			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
785		}
786		return members, nil
787	}
