806	// compiledHashKey is the canonical spelling of a job record's
807	// compiled-artifact binding field.
808	const compiledHashKey = "compiled_hash"
809	
810	// isASCIIFoldOf reports whether key names canonical under an ASCII-only
811	// letter-case fold: the two must have the same byte length and every byte
812	// must match after mapping A-Z onto a-z. JSON keys arrive here already
813	// unescaped, so a key written with a \uXXXX escape for an ASCII letter (say
814	// u0076 for "v") is judged on its decoded spelling too. A key of a different
815	// length, or one that needs a non-ASCII rune to match, returns false — use
816	// strings.EqualFold to detect those non-ASCII lookalikes separately.
817	func isASCIIFoldOf(key, canonical string) bool {
818		if len(key) != len(canonical) {
819			return false
820		}
821		for i := 0; i < len(key); i++ {
822			c := key[i]
823			if c >= 'A' && c <= 'Z' {
824				c += 'a' - 'A'
825			}
826			if c != canonical[i] {
827				return false
828			}
829		}
830		return true
831	}
