833	// isCompiledHashKey reports whether key is an accepted spelling of the
834	// compiled-artifact binding field: only "compiled_hash" itself and ASCII
835	// letter-case variants such as "COMPILED_HASH" or "CoMpIlEd_HaSh". Keys are
836	// already JSON-unescaped at this point, so an escaped spelling of any of
837	// these forms lands here too. Non-ASCII letters are never folded here.
838	func isCompiledHashKey(key string) bool {
839		return isASCIIFoldOf(key, compiledHashKey)
840	}
