842	// jobVersionKey is the canonical spelling of a job record's pinned circuit
843	// version field. The version names the frozen circuit — and thereby its
844	// trusted setup and compiled artifact — the job belongs to.
845	const jobVersionKey = "version"
846	
847	// isJobVersionKey reports whether key names a job record's pinned circuit
848	// version field under any spelling the ordinary decode fills Version from:
849	// canonical "version", an ASCII letter-case variant such as "VERSION" or
850	// "VeRsIoN", or a JSON-escaped spelling that unescapes onto either (keys
851	// arrive here already unescaped). Because encoding/json's struct-tag matching
852	// folds with Unicode case rules (strings.EqualFold), the long-s "verſion"
853	// (U+017F, written directly or as the u017f escape) names the field too.
854	func isJobVersionKey(key string) bool {
855		return strings.EqualFold(key, jobVersionKey)
856	}
