858	// rejectAmbiguousJobVersion enforces the pinned-version uniqueness rule shared
859	// by the directory read (scanJobArrayDuplicates) and the single-record decode
860	// (persistJob.UnmarshalJSON): the version a job writes is the sole authority
861	// for which frozen circuit — and therefore which trusted setup and compiled
862	// artifact — the job belongs to, so one record may carry the field under at
863	// most one recognized spelling (isJobVersionKey). Two spellings on one record
864	// make the bound version depend on key order, since encoding/json keeps the
865	// last value, and corrupt the read: the whole record is refused whether the
866	// values agree or differ, whether both are legal versions, and whether
867	// unrelated members sit between them — neither value is ever picked to carry
868	// on. A single spelling of any recognized kind — including a lone long-s
869	// "verſion" — is the one version field and keeps its current reading.
870	//
871	// keys are the record's member keys in any order; the recognized spellings
872	// are filtered and sorted here so the message is deterministic. where names
873	// the record exactly as the calling read path already computes it (by id when
874	// known, else by position), so both paths locate the problem the same way.
875	func rejectAmbiguousJobVersion(where string, keys []string) error {
876		var versionKeys []string
877		for _, key := range keys {
878			if isJobVersionKey(key) {
879				versionKeys = append(versionKeys, key)
880			}
881		}
882		if len(versionKeys) <= 1 {
883			return nil
884		}
885		sort.Strings(versionKeys)
886		quoted := make([]string, len(versionKeys))
887		for i, k := range versionKeys {
888			quoted[i] = strconv.Quote(k)
889		}
890		return corruptf("%s carries the pinned version field %q more than once (as %s)",
891			where, jobVersionKey, strings.Join(quoted, ", "))
892	}
893	
894	// compiledHashLookalike reports a member key encoding/json would match onto
895	// the binding field's struct tag yet which is not an accepted ASCII spelling
896	// (isCompiledHashKey). Struct-tag matching in encoding/json folds with the
897	// Unicode simple case-folding rules (bytes.EqualFold), so a non-ASCII
898	// lookalike — "compiled_haſh" with U+017F long s, whether written directly
899	// or as the JSON escape u017f — silently fills CompiledHash and would let a
900	// damaged binding (null above all) read as unbound, then vanish on the next
901	// commit. Such a key is damage, regardless of its value or of a correctly
902	// spelled sibling key being present. Several aliases are reported in
903	// lexicographic order so the message is stable.
904	func compiledHashLookalike(members map[string]json.RawMessage) string {
905		var aliases []string
906		for key := range members {
907			if isCompiledHashKey(key) {
908				continue
909			}
910			if strings.EqualFold(key, compiledHashKey) {
911				aliases = append(aliases, key)
912			}
913		}
914		if len(aliases) == 0 {
915			return ""
916		}
917		sort.Strings(aliases)
918		return aliases[0]
919	}
