921	// Strict decoding of the compiled-artifact binding on a committed job record.
922	//
923	// compiled_hash is a field whose presence is meaningful: records written
924	// before bindings existed simply omit it, and an explicit "" is the unbound
925	// state. But once the key appears its value must be a JSON string. A null is
926	// not "no binding" — it is damage to a binding the record claims to carry,
927	// and so is a number, boolean, array or object in its place. Reading either
928	// as the zero string would silently turn a bound job into an unbound one
929	// (and the next commit would drop the field entirely), so the read is
930	// refused as data corruption instead. A repeated key — including one
931	// repeated through JSON string escapes, even with identical values — is
932	// likewise refused rather than resolved to its last value. A legal non-empty
933	// string keeps being matched against the pinned version's artifact by
934	// validateEnvelope, exactly as written.
935	//
936	// The field is recognized under any ASCII letter-case spelling, so a record
937	// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
938	// same binding and follows the same rules: a single such key is read with
939	// the full string validation above, and two spellings of the field on one
940	// record — even with byte-identical values — are a duplicate binding and
941	// corrupt the read rather than being resolved by key order.
942	//
943	// Non-ASCII spellings are not accepted even though encoding/json itself
944	// would fold them onto the field: its struct-tag matching uses Unicode case
945	// folding, under which "compiled_haſh" (U+017F long s, written directly or
946	// as the JSON escape u017f) names CompiledHash just like "compiled_hash".
947	// Such a lookalike is damage to the binding the record claims to carry and
948	// is refused whatever its value — null, a legal hash or an explicit "" —
949	// and even when a correctly spelled "compiled_hash" sits beside it, in
950	// either key order and whether the two values agree. The damaged binding
951	// must never read as an unbound job and disappear on the next commit.
952	//
953	// The pinned version field is held to a uniqueness rule of its own, enforced
954	// through rejectAmbiguousJobVersion — the same rule the directory read
955	// applies, so a record is judged identically by both paths. Every spelling
956	// the ordinary decode below fills Version from counts as that one field
957	// (isJobVersionKey): canonical "version", an ASCII letter-case variant such
958	// as "VERSION", and, since struct-tag matching folds with Unicode case rules,
959	// the long-s "verſion" (U+017F, direct or u017f-escaped); keys are compared
960	// after JSON unescaping, so an escaped spelling lands here too. Two such
961	// spellings on one record are refused as data corruption whether the values
962	// agree or differ, whether both values are legal versions, and even when
963	// unrelated fields are interleaved between them. A non-ASCII "verſion" is
964	// refused only when another recognized spelling sits beside it; appearing by
965	// itself it is the single version field and keeps the current reading (the
966	// ordinary decode folds it onto Version). A single spelling of any kind keeps
967	// its current value and spelling compatibility, and an illegal single value —
968	// a string, a float, null, or a non-positive version — is rejected exactly as
969	// before, by the decode or validateEnvelope.
970	//
971	// Only these two job fields are judged here; every other field keeps the
972	// ordinary struct decoding.
973	func (j *persistJob) UnmarshalJSON(raw []byte) error {
974		const what = "stored job record"
975		if string(bytes.TrimSpace(raw)) == "null" {
976			return corruptf("%s must be a JSON object, not null", what)
977		}
978		// Name the job up front, best-effort, so a failure of the strict member
979		// walk below — an exact duplicate key is rejected there before a member map
980		// exists — still locates the record it came from. This probe only labels
981		// errors: a missing, non-string or undecodable id leaves the generic name,
982		// and the id is decoded for real by the ordinary pass later.
983		where := what
984		var idProbe struct {
985			ID string `json:"id"`
986		}
987		if err := json.Unmarshal(raw, &idProbe); err == nil && idProbe.ID != "" {
988			where = fmt.Sprintf("stored job record %q", idProbe.ID)
989		}
990		members, err := strictObjectMembers(raw, where, nil)
991		if err != nil {
992			return err
993		}
994		// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
995		// matching would silently read as this field ("compiled_haſh" with long
996		// s, directly written or ſ-escaped), whatever its value and whether
997		// or not a correctly spelled key accompanies it. It must never be ignored
998		// as an unknown member, which would let a damaged binding read unbound.
999		if alias := compiledHashLookalike(members); alias != "" {
1000			return corruptf("%s carries the binding field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
1001				where, compiledHashKey, alias)
1002		}
1003		// The pinned-version uniqueness rule, shared with the directory read
1004		// (scanJobArrayDuplicates) through rejectAmbiguousJobVersion: a record
1005		// carrying two recognized spellings of the version field is ambiguous —
1006		// encoding/json keeps the last value, which would let the binding flip
1007		// depending on key order (or let an unhashed job read against a different
1008		// frozen, set-up version) — so the whole record is refused rather than
1009		// resolved by order. A long-s spelling counts here only beside another
1010		// recognized spelling; standing alone it is the single version field and
1011		// keeps the current reading handled below.
1012		memberKeys := make([]string, 0, len(members))
1013		for key := range members {
1014			memberKeys = append(memberKeys, key)
1015		}
1016		if err := rejectAmbiguousJobVersion(where, memberKeys); err != nil {
1017			return err
1018		}
1019		// With zero or one recognized spelling, the ordinary decode below already
1020		// yields the current value: a single canonical/ASCII/long-s spelling folds
1021		// onto Version, and a missing version reads as 0 and is rejected by
1022		// validateEnvelope as a job bound to an unknown circuit. Illegal single
1023		// values (a string, a float, null, zero or negative) keep being rejected by
1024		// that same decode or the envelope validation, so nothing is picked here.
1025		// Every accepted spelling of the binding field counts as the same one
1026		// field; the record may carry it at most once, however it is capitalized.
1027		var bindingKeys []string
1028		for key := range members {
1029			if isCompiledHashKey(key) {
1030				bindingKeys = append(bindingKeys, key)
1031			}
1032		}
1033		if len(bindingKeys) > 1 {
1034			sort.Strings(bindingKeys)
1035			quoted := make([]string, len(bindingKeys))
1036			for i, k := range bindingKeys {
1037				quoted[i] = strconv.Quote(k)
1038			}
1039			return corruptf("%s carries the binding field %q more than once (as %s)",
1040				where, compiledHashKey, strings.Join(quoted, ", "))
1041		}
1042		compiledHash := ""
1043		hasBinding := false
1044		if len(bindingKeys) == 1 {
1045			hash, err := storedRecordShape.string(members[bindingKeys[0]], where+` field "compiled_hash"`)
1046			if err != nil {
1047				return err
1048			}
1049			compiledHash, hasBinding = hash, true
1050		}
1051		type plainJob persistJob
1052		var decoded plainJob
1053		if err := json.Unmarshal(raw, &decoded); err != nil {
1054			return corruptf("%s is not valid JSON: %v", what, err)
1055		}
1056		if hasBinding {
1057			decoded.CompiledHash = compiledHash
1058		}
1059		*j = persistJob(decoded)
1060		return nil
1061	}
