1063	// Store is a persistent workbench backed by one local data directory.
1064	//
1065	// All operations are safe for concurrent use by multiple goroutines and by
1066	// several processes pointed at the same directory: an in-process mutex plus a
1067	// process-shared flock serialize commits, and every commit is an atomic
1068	// temp-file/fsync/rename replacement. Open the directory with Open and call
1069	// Close when done.
1070	type Store struct {
1071		dir  string
1072		mu   sync.Mutex
1073		lock *os.File
1074	
1075		data envelope
1076	}
1077	
1078	// Open opens (creating if needed) the workbench data in dir. If the
1079	// directory does not exist it is created. Existing committed data is loaded
1080	// and fully validated before Open returns; on a corrupt, truncated or
1081	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
1082	// leaves every file in the directory untouched.
1083	func Open(dir string) (*Store, error) {
1084		if dir == "" {
1085			return nil, invalidf("data directory must not be empty")
1086		}
1087		if err := os.MkdirAll(dir, 0o755); err != nil {
1088			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
1089		}
1090		lockPath := filepath.Join(dir, dirLockFile)
1091		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
1092		if err != nil {
1093			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
1094		}
1095		// Serialize against other processes while we read / validate.
1096		if err := lockExclusive(lock); err != nil {
1097			lock.Close()
1098			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
1099		}
1100	
1101		s := &Store{dir: dir, lock: lock}
1102		if err := s.loadLocked(); err != nil {
1103			unlockLock(lock)
1104			lock.Close()
1105			return nil, err
1106		}
1107		// The lock is taken again per operation; holding it for the store's
1108		// lifetime would forbid two open handles on one directory.
1109		if err := unlockLock(lock); err != nil {
1110			lock.Close()
1111			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
1112		}
1113		return s, nil
1114	}
1115	
1116	// Close releases the directory lock. It does not discard committed data.
1117	func (s *Store) Close() error {
1118		s.mu.Lock()
1119		defer s.mu.Unlock()
1120		if s.lock == nil {
1121			return nil
1122		}
1123		var first error
1124		if err := unlockLock(s.lock); err != nil {
1125			first = err
1126		}
1127		if err := s.lock.Close(); err != nil && first == nil {
1128			first = err
1129		}
1130		s.lock = nil
1131		return first
1132	}
1133	
1134	// Dir reports the data directory backing the store.
1135	func (s *Store) Dir() string { return s.dir }
1136	
1137	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
1138	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
1139	
1140	// loadLocked reads and validates the committed file. Caller must hold the
1141	// exclusive flock; the in-process mutex is taken by the public Open path.
1142	func (s *Store) loadLocked() error {
1143		raw, err := os.ReadFile(s.dataPath())
1144		if errors.Is(err, os.ErrNotExist) {
1145			s.data = envelope{Format: FormatVersion}
1146			return nil
1147		}
1148		if err != nil {
1149			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
1150		}
1151		if len(strings.TrimSpace(string(raw))) == 0 {
1152			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
1153		}
1154	
1155		var env envelope
1156		if err := json.Unmarshal(raw, &env); err != nil {
1157			// Shape failures surfaced by the persisted-definition decoders are
1158			// integrity failures, not JSON syntax errors; report their detail
1159			// instead of the generic "not valid JSON" wording.
1160			var se StoreError
1161			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
1162				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
1163			}
1164			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
1165		}
1166		if env.Format == 0 {
1167			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
1168		}
1169		if env.Format != FormatVersion {
1170			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
1171				s.dataPath(), env.Format, FormatVersion)
1172		}
1173		if err := validateEnvelope(env); err != nil {
1174			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
1175		}
1176		s.data = env
1177		return nil
1178	}
1179	
1180	// commitLocked writes the pending state atomically: temp file → fsync →
1181	// rename → fsync directory. Caller must hold both the in-process mutex and
1182	// the exclusive flock; all in-memory mutations must already have happened and
1183	// been rule-checked, so a failure here occurs before any success is reported.
1184	func (s *Store) commitLocked() error {
1185		s.data.Format = FormatVersion
1186		// Stable output: records are stored sorted so files are deterministic.
1187		sortEnvelope(&s.data)
1188	
1189		payload, err := json.MarshalIndent(&s.data, "", "  ")
1190		if err != nil {
1191			return fmt.Errorf("cannot encode data: %w", err)
1192		}
1193		payload = append(payload, '\n')
1194	
1195		tmp := s.tmpPath()
1196		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
1197		if err != nil {
1198			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
1199		}
1200		if _, err := f.Write(payload); err != nil {
1201			f.Close()
1202			os.Remove(tmp)
1203			return fmt.Errorf("cannot write staged data: %w", err)
1204		}
1205		if err := f.Sync(); err != nil {
1206			f.Close()
1207			os.Remove(tmp)
1208			return fmt.Errorf("cannot flush staged data: %w", err)
1209		}
1210		if err := f.Close(); err != nil {
1211			os.Remove(tmp)
1212			return fmt.Errorf("cannot finish staged data: %w", err)
1213		}
1214		if err := os.Rename(tmp, s.dataPath()); err != nil {
1215			os.Remove(tmp)
1216			return fmt.Errorf("cannot commit data file: %w", err)
1217		}
1218		if err := syncDir(s.dir); err != nil {
1219			// The rename already happened; lack of dir fsync only weakens crash
1220			// durability, never correctness of what is visible now.
1221			return nil
1222		}
1223		return nil
1224	}
1225	
1226	// withLock runs fn under the in-process mutex and an exclusive flock, then
1227	// atomically commits when fn requests it. The on-disk state is re-read after
1228	// acquiring the lock, so concurrent commits from another process or another
1229	// handle are always observed. Operations validate before mutating; a rejected
1230	// operation (commit=false or an error) writes nothing and leaves committed
1231	// state unchanged.
1232	func (s *Store) withLock(fn func() (commit bool, err error)) error {
1233		s.mu.Lock()
1234		defer s.mu.Unlock()
1235		if s.lock == nil {
1236			return invalidf("store is closed")
1237		}
1238		if err := lockExclusive(s.lock); err != nil {
1239			return fmt.Errorf("cannot lock data directory: %w", err)
1240		}
1241		defer unlockLock(s.lock)
1242	
1243		if err := s.loadLocked(); err != nil {
1244			return err
1245		}
1246		commit, err := fn()
1247		if err != nil {
1248			return err
1249		}
1250		if !commit {
1251			return nil
1252		}
1253		return s.commitLocked()
1254	}
1255	
1256	// withLockRead runs fn under a shared flock over freshly reloaded state.
1257	func (s *Store) withLockRead(fn func() error) error {
1258		s.mu.Lock()
1259		defer s.mu.Unlock()
1260		if s.lock == nil {
1261			return invalidf("store is closed")
1262		}
1263		if err := lockShared(s.lock); err != nil {
1264			return fmt.Errorf("cannot lock data directory: %w", err)
1265		}
1266		defer unlockLock(s.lock)
1267		if err := s.loadLocked(); err != nil {
1268			return err
1269		}
1270		return fn()
1271	}
1272	
1273	func sortEnvelope(env *envelope) {
1274		sort.Slice(env.Circuits, func(i, j int) bool {
1275			if env.Circuits[i].Name != env.Circuits[j].Name {
1276				return env.Circuits[i].Name < env.Circuits[j].Name
1277			}
1278			return env.Circuits[i].Version < env.Circuits[j].Version
1279		})
1280		sort.Slice(env.Setups, func(i, j int) bool {
1281			if env.Setups[i].Name != env.Setups[j].Name {
1282				return env.Setups[i].Name < env.Setups[j].Name
1283			}
1284			return env.Setups[i].Version < env.Setups[j].Version
1285		})
1286		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
1287		sort.Slice(env.Artifacts, func(i, j int) bool {
1288			if env.Artifacts[i].Name != env.Artifacts[j].Name {
1289				return env.Artifacts[i].Name < env.Artifacts[j].Name
1290			}
1291			return env.Artifacts[i].Version < env.Artifacts[j].Version
1292		})
1293	}
1294	
1295	// validateEnvelope re-checks every invariant on load so a tampered or
1296	// hand-edited file cannot bypass the domain rules.
1297	func validateEnvelope(env envelope) error {
1298		seenCircuit := make(map[[2]string]bool)
1299		circuitOK := make(map[[2]string]bool)
1300		for i, c := range env.Circuits {
1301			key := [2]string{c.Name, itoa(c.Version)}
1302			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
1303				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
1304			}
1305			if c.Version <= 0 {
1306				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
1307			}
1308			if seenCircuit[key] {
1309				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
1310			}
1311			seenCircuit[key] = true
1312			if c.Constraints <= 0 {
1313				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
1314			}
1315			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
1316				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
1317			}
1318			// The same representability rule the write path enforces: wire 0 plus
1319			// every declared input must fit inside the platform's int. A record
1320			// beyond that bound can never have been written by this build and
1321			// cannot be checked safely, so the directory is corrupt rather than
1322			// silently narrowed or read with a wrapped-around layout.
1323			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
1324				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
1325					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
1326			}
1327			if c.Definition != nil {
1328				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
1329					return err
1330				}
1331			}
1332			circuitOK[key] = true
1333		}
1334		seenSetup := make(map[[2]string]bool)
1335		for i, p := range env.Setups {
1336			key := [2]string{p.Name, itoa(p.Version)}
1337			if !circuitOK[key] {
1338				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
1339			}
1340			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
1341			if c == nil || !c.Frozen {
1342				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
1343			}
1344			if seenSetup[key] {
1345				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
1346			}
1347			seenSetup[key] = true
1348		}
1349		seenJob := make(map[string]bool)
1350		for i, j := range env.Jobs {
1351			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
1352				return fmt.Errorf("job #%d has an empty or blank id", i+1)
1353			}
1354			if seenJob[j.ID] {
1355				return fmt.Errorf("job %q appears more than once", j.ID)
1356			}
1357			seenJob[j.ID] = true
1358			if j.Kind != "prove" {
1359				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
1360			}
1361			if j.Attempt <= 0 {
1362				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
1363			}
1364			key := [2]string{j.Circuit, itoa(j.Version)}
1365			if !circuitOK[key] {
1366				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
1367			}
1368			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
1369			if c == nil || !c.Frozen {
1370				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
1371			}
1372			if !seenSetup[key] {
1373				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
1374			}
1375			// A recorded compiled-artifact binding must still resolve against the
1376			// pinned version's artifact; a dangling or mismatched binding makes
1377			// the file unreadable rather than silently dropping the binding.
1378			if j.CompiledHash != "" {
1379				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1380				if artifact == nil {
1381					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1382				}
1383				if artifact.Hash != j.CompiledHash {
1384					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1385						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1386				}
1387			}
1388		}
1389		seenArtifact := make(map[[2]string]bool)
1390		for i, a := range env.Artifacts {
1391			key := [2]string{a.Name, itoa(a.Version)}
1392			if !circuitOK[key] {
1393				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1394			}
1395			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1396			if c == nil || !c.Frozen {
1397				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1398			}
1399			if seenArtifact[key] {
1400				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1401			}
1402			seenArtifact[key] = true
1403			if c.Definition == nil {
1404				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1405			}
1406			if a.Constraints != c.Constraints {
1407				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1408					a.Name, a.Version, a.Constraints, c.Constraints)
1409			}
1410			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1411			if err != nil {
1412				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1413			}
1414			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1415				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1416			}
1417			wantHash := artifactHash(a.Name, a.Version, def)
1418			if a.Hash != wantHash {
1419				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1420					a.Name, a.Version, a.Hash, wantHash)
1421			}
1422		}
1423		return nil
1424	}
1425	
1426	// validatePersistDefinition re-validates a stored definition against its
1427	// version's declared counts: prime modulus, in-range wires and an exact
1428	// constraint count match.
1429	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1430		parsed, err := definitionFromPersist(*def, public, private)
1431		if err != nil {
1432			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1433		}
1434		if !parsed.compatibleWith(constraints, public, private) {
1435			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1436		}
1437		return nil
1438	}
1439	
1440	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1441		for i := range cs {
1442			if cs[i].Name == name && cs[i].Version == version {
1443				return &cs[i]
1444			}
1445		}
1446		return nil
1447	}
1448	
1449	func itoa(v int) string { return fmt.Sprintf("%d", v) }
