30	// seedTwoVersionJobStore commits two frozen, set-up versions c@1 and c@2
31	// (definitions/compile are unnecessary for an unbound job) and one unbound
32	// job pinned to v1. It reproduces the ambiguity that matters: a job spelling
33	// version both as 1 and 2 has a valid target under either value.
34	func seedTwoVersionJobStore(t *testing.T) string {
35		t.Helper()
36		dir := t.TempDir()
37		s, err := Open(dir)
38		if err != nil {
39			t.Fatal(err)
40		}
41		seedFrozenSource(t, s, "c", 1, 1, 1, 1, "")
42		seedFrozenSource(t, s, "c", 2, 1, 1, 1, "")
