52	// replaceInJob scopes a literal replacement to the job object carrying id:
53	// it finds the id marker and replaces the first occurrence of old after it,
54	// so a "version": 1 shared by the circuit/setup/artifact records is never
55	// mistaken for the job's own field.
56	func replaceInJob(t *testing.T, dir, id, old, repl string) []byte {
57		t.Helper()
58		raw, err := readDataFile(t, dir)
59		if err != nil {
60			t.Fatal(err)
61		}
62		marker := `"id": "` + id + `"`
63		at := strings.Index(string(raw), marker)
64		if at < 0 {
65			t.Fatalf("committed file does not carry job marker %q", marker)
66		}
67		rel := strings.Index(string(raw[at:]), old)
68		if rel < 0 {
69			t.Fatalf("job %q does not carry %q after its id marker", id, old)
70		}
71		pos := at + rel
72		bad := string(raw[:pos]) + repl + string(raw[pos+len(old):])
73		writeDataFile(t, dir, []byte(bad))
74		return []byte(bad)
75	}
