81	// assertJobVersionCorrupt opens dir, requires ErrDataCorrupt naming id and
82	// the version field, and checks the file is still byte-for-byte want.
83	func assertJobVersionCorrupt(t *testing.T, dir, id string, want []byte) {
84		t.Helper()
85		_, err := Open(dir)
86		if !errors.Is(err, ErrDataCorrupt) {
