88		}
89		if !strings.Contains(err.Error(), strconv.Quote(id)) {
90			t.Fatalf("error does not name the ambiguous job %q: %v", id, err)
91		}
92		if !strings.Contains(err.Error(), "version") {
93			t.Fatalf("error does not name the version field: %v", err)
94		}
95		got, rerr := readDataFile(t, dir)
96		if rerr != nil {
97			t.Fatal(rerr)
98		}
99		if string(got) != string(want) {
100			t.Fatalf("open modified the damaged file")
101		}
102	}
