104	// A job carrying two recognized version spellings is refused: canonical plus
105	// an ASCII case variant or a JSON-escaped spelling, equal or differing values,
106	// both values legal. The error names the job and the version field, and the
107	// file is left byte-for-byte in place.
108	func TestJobVersionDuplicateIsCorrupt(t *testing.T) {
109		escV := jsonBackslash + "u0076ersion" // "version" as raw JSON text
110		escI := "vers" + jsonBackslash + "u0069on"
