116			{"differing values, ASCII variant", `"version": 1, "VERSION": 2`},
117			{"upper then canonical, differing", `"VERSION": 2, "version": 1`},
118			{"mixed case variant, same value", `"version": 1, "VeRsIoN": 1`},
119			{"escaped leading letter, same value", `"version": 1, "` + escV + `": 1`},
120			{"escaped inner letter, differing", `"version": 1, "` + escI + `": 2`},
