152	func TestJobVersionDuplicateInterspersedIsCorrupt(t *testing.T) {
153		dir, _ := seedBoundJobStore(t)
154		old := `"version": 1,` + jobFieldIndent + `"kind": "prove",` + jobFieldIndent + `"attempt": 1`
155		repl := `"version": 1,` + jobFieldIndent + `"kind": "prove",` + jobFieldIndent +
