226	
227	// An illegal single version value is still rejected, exactly as before: a
228	// non-positive version names no circuit and fails the integrity validation.
229	func TestJobVersionSingleIllegalValueStillRejected(t *testing.T) {
230		dir, _ := seedBoundJobStore(t)
231		replaceInJob(t, dir, "j-bound", versionLine(1), `"version": 0`)
