	if r.code != 3 || !strings.Contains(r.err, "read failed") || !strings.Contains(r.err, "compiled_hash") {
		t.Fatalf("duplicate compiled_hash: want exit 3 read failure naming the field, got code=%d err=%q", r.code, r.err)
	}
