1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// CLI contract for an ambiguous pinned version on a committed job record.
11	// Every spelling an ordinary read would take as the job's version — canonical
12	// "version", an ASCII letter-case variant, a JSON-escaped spelling, or the
13	// Unicode-folded long-s "verſion" (U+017F) — is one version field. Two of
14	// them on one record make the bound version depend on key order, so every
15	// data command fails at open with exit code 3, prints no record, names the
16	// damaged job and its version field, and leaves data.json byte-for-byte in
17	// place. A single recognized spelling (ASCII or long-s) still reads.
18	
19	// rewriteJobVersionCLI scopes a literal replacement to the committed j1 job:
20	// it replaces the first old occurring after the j1 id marker, so the shared
21	// circuit/setup/artifact "version" fields are never touched. It returns the
22	// bytes now on disk.
23	func rewriteJobVersionCLI(t *testing.T, dir, old, fragment string) []byte {
24		t.Helper()
25		path := filepath.Join(dir, "data.json")
26		raw, err := os.ReadFile(path)
27		if err != nil {
28			t.Fatal(err)
29		}
30		marker := `"id": "j1"`
31		at := strings.Index(string(raw), marker)
32		if at < 0 {
33			t.Fatalf("committed file does not carry the j1 marker %q", marker)
34		}
35		rel := strings.Index(string(raw[at:]), old)
36		if rel < 0 {
37			t.Fatalf("j1 job does not carry %q after its id marker", old)
38		}
39		pos := at + rel
40		bad := []byte(string(raw[:pos]) + fragment + string(raw[pos+len(old):]))
41		if err := os.WriteFile(path, bad, 0o644); err != nil {
42			t.Fatal(err)
43		}
44		return bad
45	}
46	
47	// TestCLIJobVersionAmbiguousExitCode: two recognized version spellings on j1 —
48	// ASCII variants, JSON-escaped spellings, or a long-s spelling beside a
49	// recognized one, equal or differing values — make every data command exit 3
50	// with no output and leave data.json byte-for-byte in place.
51	func TestCLIJobVersionAmbiguousExitCode(t *testing.T) {
52		direct := "ver" + cliLongS + "ion"
53		escapedLongS := "ver" + cliJSONEscape + "u017f" + "ion"
54		escV := cliJSONEscape + "u0076ersion"
55		cases := []struct {
56			name     string
57			fragment string
58		}{
59			{"canonical plus upper, same value", `"version": 1, "VERSION": 1`},
60			{"canonical plus upper, differing", `"version": 1, "VERSION": 2`},
61			{"upper then canonical", `"VERSION": 2, "version": 1`},
62			{"mixed case", `"version": 1, "VeRsIoN": 1`},
63			{"escaped exact spelling", `"version": 1, "` + escV + `": 1`},
64			{"canonical plus direct long s", `"version": 1, "` + direct + `": 1`},
65			{"direct long s then canonical, differing", `"` + direct + `": 2, "version": 1`},
66			{"canonical plus escaped long s", `"version": 1, "` + escapedLongS + `": 1`},
67		}
68		for _, tc := range cases {
69			t.Run(tc.name, func(t *testing.T) {
70				dir := filepath.Join(t.TempDir(), "bench")
71				hash := seedBoundJobCLI(t, dir)
72				bad := rewriteJobVersionCLI(t, dir, `"version": 1`, tc.fragment)
73	
74				commands := [][]string{
75					{"job-get", "--dir", dir, "--id", "j1"},
76					{"job-list", "--dir", dir},
77					{"job-submit", "--dir", dir, "--id", "j2", "--name", "mul", "--version", "1"},
78					{"circuit-list", "--dir", dir},
79					{"circuit-create", "--dir", dir, "--name", "other", "--version", "1"},
80				}
81				for _, args := range commands {
82					r := callCLI(t, args...)
83					if r.code != 3 {
84						t.Fatalf("%s: want exit 3, got %d (out=%q err=%q)", args[0], r.code, r.out, r.err)
85					}
86					if r.out != "" {
87						t.Fatalf("%s printed a record despite corruption: %q", args[0], r.out)
88					}
89					if !strings.Contains(r.err, "read failed") || !strings.Contains(r.err, "data corrupt") {
90						t.Fatalf("%s: unexpected error text %q", args[0], r.err)
91					}
92					if !strings.Contains(r.err, `"j1"`) || !strings.Contains(r.err, "version") {
93						t.Fatalf("%s: error does not name the damaged job and version field: %q", args[0], r.err)
94					}
95				}
96	
97				// The compiled hash the job carries is still on disk verbatim.
98				if !strings.Contains(string(bad), `"compiled_hash": "`+hash+`"`) {
99					t.Fatalf("damaged fragment lost the bound compiled hash")
100				}
101				left, err := os.ReadFile(filepath.Join(dir, "data.json"))
102				if err != nil {
103					t.Fatal(err)
104				}
105				if string(left) != string(bad) {
106					t.Fatalf("data.json changed after refused commands")
107				}
108			})
109		}
110	}
