112	// TestCLIJobVersionSingleASCIISpellingStillReads: one recognized spelling of
113	// version, ASCII variant or a long-s fold, keeps the job pinned to v1 and
114	// preserves its compiled hash.
115	func TestCLIJobVersionSingleSpellingStillReads(t *testing.T) {
116		directLongS := "ver" + cliLongS + "ion"
117		escLongS := "ver" + cliJSONEscape + "u017f" + "ion"
118		escS := "ver" + cliJSONEscape + "u0073" + "ion"
119		for _, tc := range []struct {
120			name string
121			key  string
122		}{
123			{"upper case", "VERSION"},
124			{"mixed case", "VeRsIoN"},
125			{"escaped letter", escS},
126			{"direct long s", directLongS},
127			{"escaped long s", escLongS},
128		} {
129			t.Run(tc.name, func(t *testing.T) {
130				dir := filepath.Join(t.TempDir(), "bench")
131				hash := seedBoundJobCLI(t, dir)
132				rewriteJobVersionCLI(t, dir, `"version": 1`, `"`+tc.key+`": 1`)
133	
134				r := callCLI(t, "job-get", "--dir", dir, "--id", "j1")
135				if r.code != 0 {
136					t.Fatalf("single spelling %q must load: code=%d err=%s", tc.key, r.code, r.err)
137				}
138				if !strings.Contains(r.out, "version=1") || !strings.Contains(r.out, "compiled_hash="+hash) {
139					t.Fatalf("single spelling %q not read as v1 with binding: %q", tc.key, r.out)
140				}
141			})
142		}
143	}
