1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7	)
8	
9	// This file is the single source of the structural rules every constraint
10	// definition document follows, on both of its read paths: a JSON file
11	// imported by the user (parseDefinitionJSON in constraints.go) and a
12	// definition already committed in the data directory
13	// (persistDefinition.UnmarshalJSON). The two paths used to each maintain
14	// their own copy of the same three-level shape checks; they now share this
15	// one schema, so the structure they accept can never drift apart.
16	//
17	// The shared rules cover exactly the three-level shape — definition,
18	// constraint, term:
19	//
20	//	definition: an object naming "modulus" and "constraints" exactly once
21	//	constraint: an object naming "a", "b" and "c" exactly once
22	//	term:       an object naming "wire" and "coeff" exactly once
23	//
24	// Every required field must be present and non-null; unknown fields, repeated
25	// fields (including the same field spelled twice through JSON string
26	// escapes, even with identical values) and wrongly typed values are all
27	// rejected. An explicitly empty term array is the zero linear combination and
28	// an explicit wire 0 names the constant wire: both are ordinary values, never
29	// defaults for a missing field.
30	//
31	// The paths differ only in how a structural failure is reported — the import
32	// path rejects the request with ErrInvalidArgument, the committed-data path
33	// refuses the read with ErrDataCorrupt — and in the words each uses to name
34	// the document. Everything else is one rule set. The semantic domain rules
35	// (prime modulus, constraint count, wire layout, coefficient grammar) are
36	// likewise shared: they live in definitionShape.canonicalize and run after
37	// this structural decode on both paths.
38	//
39	// One scan, not three. The document is tokenized a single time into the
40	// jvalue tree: syntax is checked by the one leading json.Unmarshal and the
41	// tree walk accounts for every object member exactly once, so a repeated key
42	// nested many levels deep is seen during that one descent instead of once per
43	// enclosing object. The outer definition, every constraint and every term all
44	// take their members from the same tree; nothing is re-unmarshaled or
45	// re-walked per level. The order in which findings are surfaced is fixed
46	// exactly as it was before the consolidation: syntax first, then an unknown
47	// top-level field, then the first repeated key anywhere in the document (a
48	// document-level finding, never attributed to one constraint), and only then
49	// the level-by-level shape and type checks.
50	
51	// jsonShape is the strict-JSON rule set the definition schema is built from:
52	// objects name only allowed keys, required members are present, scalars have
53	// their declared JSON type and no object repeats a key. The fail constructor
54	// tags each rejection with the reading path's error kind; nullSuffix is
55	// appended to object/array null rejections so the committed-data path can
56	// name null explicitly where the import grammar simply rejects the shape.
57	type jsonShape struct {
58		fail       func(format string, args ...any) error
59		nullSuffix string
60	}
61	
62	// jvalue is one JSON value as found during the single structural tokenization
63	// pass. Objects keep their members in document order; raw is the value's own
64	// byte span within the document (the key text excluded), which the later
65	// typed reads slice directly instead of re-decoding the surrounding document.
66	// A null member is represented by kind == jnull; scalar leaves carry their
67	// json token already decoded (string/number/bool), so scalar type checks need
68	// no second parse to *decide the type* — only the error text of a rejected
69	// scalar goes through json.Unmarshal, keeping the diagnostic byte-identical.
70	type jvalue struct {
71		kind    byte // '{', '[', 's' string, 'n' number, 'b' bool, '0' null
72		raw     []byte
73		str     string
74		boolean bool
75		members []jmember
76		items   []*jvalue
77	}
78	
79	// jmember is one object value paired with its already-JSON-unescaped key.
80	type jmember struct {
81		key   string
82		value *jvalue
83	}
84	
85	// documentBuilder is the state of the one structural tokenization: it owns
86	// the decoder and remembers the first repeated key in token order while the
87	// whole document is still walked, so an unknown top-level field encountered
88	// later in the document is allowed to win over a deeper duplicate, exactly as
89	// the unmarshal-then-walk ordering did before consolidation.
90	type documentBuilder struct {
91		shape  jsonShape
92		dec    *json.Decoder
93		doc    []byte
94		what   string
95		dupErr error // first duplicate field, surfaced only after the top scan
96	}
97	
98	// valueStartAfterKey returns the offset at which an object member's value
99	// begins: after a key token the decoder is positioned at the colon, so skip
100	// the colon and surrounding JSON whitespace. The leading grammar pass already
101	// proved a colon and value follow, so the scan is exact.
102	func (b *documentBuilder) valueStartAfterKey() int64 {
103		i := b.dec.InputOffset()
104		isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' }
105		for i < int64(len(b.doc)) && isSpace(b.doc[i]) {
106			i++
107		}
108		if i < int64(len(b.doc)) && b.doc[i] == ':' {
109			i++
110		}
111		for i < int64(len(b.doc)) && isSpace(b.doc[i]) {
112			i++
113		}
114		return i
115	}
116	
117	// parseJValue decodes the complete JSON value the decoder is positioned at,
118	// tracking the raw span and, for objects, recording a repeated member key.
119	// Keys are compared after JSON unescaping (the decoder already unescapes the
120	// key token), so a key repeated through a \uXXXX spelling is a duplicate even
121	// when both values are byte-identical. Every token of the document is visited
122	// exactly once in this single descent; a duplicate does not stop the walk, so
123	// every top-level member is still seen before any finding is surfaced.
124	func (b *documentBuilder) parseJValue(start int64) (*jvalue, error) {
125		tok, err := b.dec.Token()
126		if err != nil {
127			return nil, b.shape.fail("%s is not valid JSON: %v", b.what, err)
128		}
129		switch v := tok.(type) {
130		case json.Delim:
131			switch v {
132			case '{':
133				out := &jvalue{kind: '{'}
134				seen := make(map[string]bool)
135				for b.dec.More() {
136					keyTok, err := b.dec.Token()
137					if err != nil {
138						return nil, b.shape.fail("%s is not valid JSON: %v", b.what, err)
139					}
140					key := keyTok.(string)
141					if seen[key] && b.dupErr == nil {
142						b.dupErr = b.shape.fail("%s contains duplicate field %q", b.what, key)
143					}
144					seen[key] = true
145					child, err := b.parseJValue(b.valueStartAfterKey())
146					if err != nil {
147						return nil, err
148					}
149					out.members = append(out.members, jmember{key: key, value: child})
150				}
151				if _, err := b.dec.Token(); err != nil { // closing brace
152					return nil, b.shape.fail("%s is not valid JSON: %v", b.what, err)
153				}
154				out.raw = b.doc[start:b.dec.InputOffset()]
155				return out, nil
156			case '[':
157				out := &jvalue{kind: '['}
158				for b.dec.More() {
159					child, err := b.parseJValue(b.dec.InputOffset())
160					if err != nil {
161						return nil, err
162					}
163					out.items = append(out.items, child)
164				}
165				if _, err := b.dec.Token(); err != nil { // closing bracket
166					return nil, b.shape.fail("%s is not valid JSON: %v", b.what, err)
167				}
168				out.raw = b.doc[start:b.dec.InputOffset()]
169				return out, nil
170			}
171		case string:
172			return &jvalue{kind: 's', raw: b.doc[start:b.dec.InputOffset()], str: v}, nil
173		case json.Number:
174			return &jvalue{kind: 'n', raw: b.doc[start:b.dec.InputOffset()]}, nil
175		case bool:
176			return &jvalue{kind: 'b', raw: b.doc[start:b.dec.InputOffset()], boolean: v}, nil
177		case nil:
178			return &jvalue{kind: '0', raw: b.doc[start:b.dec.InputOffset()]}, nil
179		}
180		return nil, b.shape.fail("%s is not valid JSON", b.what)
181	}
182	
183	// buildDocumentTree applies the object-shape gate, then one grammar pass, then
184	// one whole-document walk, returning the value tree and the first repeated
185	// key found. The gate and the grammar pass reproduce the original object()
186	// precedence exactly: a null document is named as such, a document that does
187	// not start with '{' (an empty input, an array, a scalar) is "must be a JSON
188	// object" without a grammar parse, and only an object candidate is fully
189	// parsed, which also rejects trailing data after the single top-level value.
190	//
191	// The walk is the single place a repeated object key is detected at any
192	// depth. The what argument names the whole document: a duplicate nested in a
193	// constraint or a term is, as before, a document-level finding rather than a
194	// per-constraint one. dupErr is deferred: the caller checks the top-level
195	// field set first, so an unknown top-level field still outranks a deeper
196	// duplicate.
197	func (s jsonShape) buildDocumentTree(raw []byte, what string) (root *jvalue, dupErr error, err error) {
198		trimmed := bytes.TrimSpace(raw)
199		if string(trimmed) == "null" {
200			return nil, nil, s.fail("%s must be a JSON object%s", what, s.nullSuffix)
201		}
202		if len(trimmed) == 0 || trimmed[0] != '{' {
203			return nil, nil, s.fail("%s must be a JSON object", what)
204		}
205		// One grammar pass over the whole document before any member is judged:
206		// json.Unmarshal also rejects trailing data after the top-level value,
207		// including a second complete value, with its own wording.
208		var head json.RawMessage
209		if err := json.Unmarshal(trimmed, &head); err != nil {
210			return nil, nil, s.fail("%s is not valid JSON: %v", what, err)
211		}
212		b := &documentBuilder{
213			shape: s,
214			dec:   json.NewDecoder(bytes.NewReader(trimmed)),
215			doc:   trimmed,
216			what:  what,
217		}
218		b.dec.UseNumber()
219		vroot, err := b.parseJValue(0)
220		if err != nil {
221			return nil, nil, err
222		}
223		return vroot, b.dupErr, nil
224	}
225	
226	// member looks up a named member of an object value.
227	func (v *jvalue) member(key string) (*jvalue, bool) {
228		for i := range v.members {
229			if v.members[i].key == key {
230				return v.members[i].value, true
231			}
232		}
233		return nil, false
234	}
235	
236	// requireObject rejects anything that is not an object (null included) and
237	// returns the value. The nullSuffix distinguishes the committed-data wording
238	// ("…, not null") from the import wording, which simply names the shape.
239	func (s jsonShape) requireObject(v *jvalue, what string) (*jvalue, error) {
240		if v == nil || v.kind != '{' {
241			if v != nil && v.kind == '0' {
242				return nil, s.fail("%s must be a JSON object%s", what, s.nullSuffix)
243			}
244			return nil, s.fail("%s must be a JSON object", what)
245		}
246		return v, nil
247	}
248	
249	// allowOnlyMembers rejects an object carrying any key outside allowed. It
250	// inspects only this object's own level; nested objects are judged when their
251	// own level is read.
252	func (s jsonShape) allowOnlyMembers(v *jvalue, allowed []string, what string) error {
253		allowedSet := make(map[string]bool, len(allowed))
254		for _, k := range allowed {
255			allowedSet[k] = true
256		}
257		for _, m := range v.members {
258			if !allowedSet[m.key] {
259				return s.fail("%s has unknown field %q", what, m.key)
260			}
261		}
262		return nil
263	}
264	
265	// requiredMember returns a required member of an object value from the
266	// single-pass tree.
267	func (s jsonShape) requiredMember(v *jvalue, key, what string) (*jvalue, error) {
268		m, ok := v.member(key)
269		if !ok {
270			return nil, s.fail("%s is missing required field %q", what, key)
271		}
272		return m, nil
273	}
274	
275	// arrayElements requires v to be an array and returns its element values.
276	// Null is rejected: a required array must be provided explicitly, even when
277	// empty. A wrongly typed value keeps its unmarshal error text.
278	func (s jsonShape) arrayElements(v *jvalue, what string) ([]*jvalue, error) {
279		if v.kind == '0' {
280			return nil, s.fail("%s must be an array%s", what, s.nullSuffix)
281		}
282		if v.kind != '[' {
283			var elements []json.RawMessage
284			if err := json.Unmarshal(v.raw, &elements); err != nil {
285				return nil, s.fail("%s must be an array: %v", what, err)
286			}
287		}
288		return v.items, nil
289	}
290	
291	// string requires a JSON string and returns it.
292	func (s jsonShape) stringValue(v *jvalue, what string) (string, error) {
293		if v.kind == 's' {
294			return v.str, nil
295		}
296		if v.kind == '0' {
297			return "", s.fail("%s must be a JSON string, not null", what)
298		}
299		var out string
300		if err := json.Unmarshal(v.raw, &out); err != nil {
301			return "", s.fail("%s must be a JSON string: %v", what, err)
302		}
303		return out, nil
304	}
305	
306	// int requires a JSON integer (no floats, strings, null, booleans).
307	func (s jsonShape) intValue(v *jvalue, what string) (int, error) {
308		if v.kind == '0' {
309			return 0, s.fail("%s must be a JSON integer, not null", what)
310		}
311		if v.kind == 'n' {
312			var n int
313			if err := json.Unmarshal(v.raw, &n); err != nil {
314				return 0, s.fail("%s must be a JSON integer: %v", what, err)
315			}
316			return n, nil
317		}
318		var n int
319		if err := json.Unmarshal(v.raw, &n); err != nil {
320			return 0, s.fail("%s must be a JSON integer", what)
321		}
322		return n, nil
323	}
324	
325	// ---- raw-member helpers for the committed record decoders -----------------
326	//
327	// The circuit and job records in data.json are decoded member-by-member from
328	// a json.RawMessage map (see strictObjectMembers in store.go), one level per
329	// record with the values left to their own decoders. These four helpers read
330	// one such already-isolated raw member: a required lookup and the strict
331	// string/integer/boolean scalars. They share the jsonShape error tagging but
332	// operate on raw members rather than the definition document tree.
333	
334	// requireRaw returns the raw value of a required member.
335	func (s jsonShape) require(members map[string]json.RawMessage, key, what string) (json.RawMessage, error) {
336		raw, ok := members[key]
337		if !ok {
338			return nil, s.fail("%s is missing required field %q", what, key)
339		}
340		return raw, nil
341	}
342	
343	// string decodes a raw required member as a JSON string.
344	func (s jsonShape) string(raw json.RawMessage, what string) (string, error) {
345		if string(bytes.TrimSpace(raw)) == "null" {
346			return "", s.fail("%s must be a JSON string, not null", what)
347		}
348		var v string
349		if err := json.Unmarshal(raw, &v); err != nil {
350			return "", s.fail("%s must be a JSON string: %v", what, err)
351		}
352		return v, nil
353	}
354	
355	// int decodes a raw required member as a JSON integer (no floats, strings,
356	// null).
357	func (s jsonShape) int(raw json.RawMessage, what string) (int, error) {
358		trimmed := bytes.TrimSpace(raw)
359		if string(trimmed) == "null" || len(trimmed) == 0 {
360			return 0, s.fail("%s must be a JSON integer, not null", what)
361		}
362		if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
363			return 0, s.fail("%s must be a JSON integer", what)
364		}
365		var n int
366		if err := json.Unmarshal(raw, &n); err != nil {
367			return 0, s.fail("%s must be a JSON integer: %v", what, err)
368		}
369		return n, nil
370	}
371	
372	// bool decodes a raw required member as a JSON boolean (true/false; not null,
373	// a number or a string).
374	func (s jsonShape) bool(raw json.RawMessage, what string) (bool, error) {
375		trimmed := bytes.TrimSpace(raw)
376		if string(trimmed) == "true" {
377			return true, nil
378		}
379		if string(trimmed) == "false" {
380			return false, nil
381		}
382		if string(trimmed) == "null" || len(trimmed) == 0 {
383			return false, s.fail("%s must be a JSON boolean, not null", what)
384		}
385		return false, s.fail("%s must be a JSON boolean", what)
386	}
387	
388	// ---- the shared three-level definition shape ------------------------------
389	
390	// definitionShape is a constraint definition document after the shared
391	// structural decode and before any domain rule is applied: the modulus text
392	// as written and, for each constraint, its three term arrays.
393	type definitionShape struct {
394		modulus     string
395		constraints []constraintShape
396	}
397	
398	// constraintShape is one structurally decoded {"a":[…],"b":[…],"c":[…]}.
399	type constraintShape struct {
400		a, b, c []termShape
401	}
402	
403	// termShape is one structurally decoded {"wire":int,"coeff":string}.
404	type termShape struct {
405		wire  int
406		coeff string
407	}
408	
409	// definitionShapeSource carries everything that differs between the two
410	// definition read paths: the error kind failures are tagged with and the
411	// names used to describe the document. The structural rules themselves are
412	// shared verbatim.
413	type definitionShapeSource struct {
414		shape      jsonShape
415		definition string // names the definition object
416		modulus    string // names the modulus field
417		constraint string // names one constraint object
418		// term names one term object, given its side and 0-based position.
419		term func(side string, index int) string
420		// wrapConstraint adds the 1-based constraint position to a failure
421		// inside it; nil leaves the failure unadorned.
422		wrapConstraint func(index int, err error) error
423	}
424	
425	// importDefinitionSource describes a definition document supplied by the
426	// user through the import file: failures reject the request as invalid
427	// arguments, and constraints and terms are named with their positions.
428	var importDefinitionSource = definitionShapeSource{
429		shape:      jsonShape{fail: invalidf},
430		definition: "constraint definition",
431		modulus:    "modulus",
432		constraint: "constraint",
433		term: func(side string, index int) string {
434			return fmt.Sprintf("term %s[%d]", side, index)
435		},
436		wrapConstraint: func(index int, err error) error {
437			return fmt.Errorf("constraint #%d: %w", index+1, err)
438		},
439	}
440	
441	// storedDefinitionSource describes a definition committed in the data file:
442	// the same structural damage is an integrity failure of committed data, so
443	// failures are tagged as data corruption and null is named explicitly.
444	var storedDefinitionSource = definitionShapeSource{
445		shape:      jsonShape{fail: corruptf, nullSuffix: ", not null"},
446		definition: "stored constraint definition",
447		modulus:    "stored modulus",
448		constraint: "stored constraint",
449		term: func(side string, index int) string {
450			return "stored term"
451		},
452	}
453	
454	// decodeDefinitionShape applies the shared structural rules to a raw
455	// definition document: exactly the modulus and constraints fields at the top
456	// level, exactly the a/b/c arrays per constraint and exactly the wire/coeff
457	// pair per term, each present, non-null and correctly typed.
458	//
459	// The document is tokenized once into a tree, and that one tree answers every
460	// level. Findings surface in the fixed order grammar/shape gate → unknown
461	// top-level field → repeated key anywhere → level-by-level required-field and
462	// type checks.
463	func decodeDefinitionShape(raw []byte, src definitionShapeSource) (definitionShape, error) {
464		obj, dupErr, err := src.shape.buildDocumentTree(raw, src.definition)
465		if err != nil {
466			return definitionShape{}, err
467		}
468		// buildDocumentTree has already enforced the object gate, so obj is an
469		// object here. An unknown top-level field outranks a deeper duplicate;
470		// only afterwards is the first repeated key anywhere surfaced.
471		if err := src.shape.allowOnlyMembers(obj, []string{"modulus", "constraints"}, src.definition); err != nil {
472			return definitionShape{}, err
473		}
474		if dupErr != nil {
475			return definitionShape{}, dupErr
476		}
477		modulusRaw, err := src.shape.requiredMember(obj, "modulus", src.definition)
478		if err != nil {
479			return definitionShape{}, err
480		}
481		constraintsRaw, err := src.shape.requiredMember(obj, "constraints", src.definition)
482		if err != nil {
483			return definitionShape{}, err
484		}
485		modulusText, err := src.shape.stringValue(modulusRaw, src.modulus)
486		if err != nil {
487			return definitionShape{}, err
488		}
489		constraintValues, err := src.shape.arrayElements(constraintsRaw, src.definition+` field "constraints"`)
490		if err != nil {
491			return definitionShape{}, err
492		}
493		out := definitionShape{
494			modulus:     modulusText,
495			constraints: make([]constraintShape, 0, len(constraintValues)),
496		}
497		for i, cval := range constraintValues {
498			con, err := decodeConstraintValue(cval, src)
499			if err != nil {
500				if src.wrapConstraint != nil {
501					return definitionShape{}, src.wrapConstraint(i, err)
502				}
503				return definitionShape{}, err
504			}
505			out.constraints = append(out.constraints, con)
506		}
507		return out, nil
508	}
509	
510	// decodeConstraintValue decodes one {"a":[…],"b":[…],"c":[…]} value taken
511	// from the shared tree.
512	func decodeConstraintValue(v *jvalue, src definitionShapeSource) (constraintShape, error) {
513		obj, err := src.shape.requireObject(v, src.constraint)
514		if err != nil {
515			return constraintShape{}, err
516		}
517		if err := src.shape.allowOnlyMembers(obj, []string{"a", "b", "c"}, src.constraint); err != nil {
518			return constraintShape{}, err
519		}
520		var out constraintShape
521		for _, side := range []struct {
522			key string
523			dst *[]termShape
524		}{
525			{"a", &out.a}, {"b", &out.b}, {"c", &out.c},
526		} {
527			sideRaw, err := src.shape.requiredMember(obj, side.key, src.constraint)
528			if err != nil {
529				return constraintShape{}, err
530			}
531			terms, err := decodeTermArrayValue(sideRaw, src, side.key)
532			if err != nil {
533				return constraintShape{}, err
534			}
535			*side.dst = terms
536		}
537		return out, nil
538	}
539	
540	// decodeTermArrayValue decodes one a/b/c side: an explicit array (possibly
541	// empty) of term objects, read from the shared tree.
542	func decodeTermArrayValue(v *jvalue, src definitionShapeSource, side string) ([]termShape, error) {
543		termValues, err := src.shape.arrayElements(v, fmt.Sprintf("%s side %q", src.constraint, side))
544		if err != nil {
545			return nil, err
546		}
547		terms := make([]termShape, 0, len(termValues))
548		for j, tval := range termValues {
549			term, err := decodeTermValue(tval, src, side, j)
550			if err != nil {
551				return nil, err
552			}
553			terms = append(terms, term)
554		}
555		return terms, nil
556	}
557	
558	// decodeTermValue decodes one {"wire":int,"coeff":string} value taken from
559	// the shared tree.
560	func decodeTermValue(v *jvalue, src definitionShapeSource, side string, index int) (termShape, error) {
561		what := src.term(side, index)
562		obj, err := src.shape.requireObject(v, what)
563		if err != nil {
564			return termShape{}, err
565		}
566		if err := src.shape.allowOnlyMembers(obj, []string{"wire", "coeff"}, what); err != nil {
567			return termShape{}, err
568		}
569		wireRaw, err := src.shape.requiredMember(obj, "wire", what)
570		if err != nil {
571			return termShape{}, err
572		}
573		coeffRaw, err := src.shape.requiredMember(obj, "coeff", what)
574		if err != nil {
575			return termShape{}, err
576		}
577		wire, err := src.shape.intValue(wireRaw, what+" wire")
578		if err != nil {
579			return termShape{}, err
580		}
581		coeff, err := src.shape.stringValue(coeffRaw, what+" coefficient")
582		if err != nil {
583			return termShape{}, err
584		}
585		return termShape{wire: wire, coeff: coeff}, nil
586	}
587	
588	// ---- conversions between the shape and the persisted form -----------------
589	
590	// toPersist renders the structural decode in the persisted shape. Empty term
591	// arrays stay explicit empty arrays (never null), matching what the importer
592	// writes.
593	func (s definitionShape) toPersist() persistDefinition {
594		out := persistDefinition{
595			Modulus:     s.modulus,
596			Constraints: make([]persistConstraint, 0, len(s.constraints)),
597		}
598		for _, con := range s.constraints {
599			out.Constraints = append(out.Constraints, persistConstraint{
600				A: termsToPersist(con.a),
601				B: termsToPersist(con.b),
602				C: termsToPersist(con.c),
603			})
604		}
605		return out
606	}
607	
608	func termsToPersist(terms []termShape) []persistTerm {
609		out := make([]persistTerm, 0, len(terms))
610		for _, t := range terms {
611			out = append(out, persistTerm{Wire: t.wire, Coeff: t.coeff})
612		}
613		return out
614	}
615	
616	// shapeFromPersist views an already-decoded stored definition as the shared
617	// structural shape, so the domain rules can re-run without a JSON round
618	// trip.
619	func shapeFromPersist(p persistDefinition) definitionShape {
620		out := definitionShape{
621			modulus:     p.Modulus,
622			constraints: make([]constraintShape, 0, len(p.Constraints)),
623		}
624		for _, con := range p.Constraints {
625			out.constraints = append(out.constraints, constraintShape{
626				a: termsFromPersist(con.A),
627				b: termsFromPersist(con.B),
628				c: termsFromPersist(con.C),
629			})
630		}
631		return out
632	}
633	
634	func termsFromPersist(terms []persistTerm) []termShape {
635		out := make([]termShape, 0, len(terms))
636		for _, t := range terms {
637			out = append(out, termShape{wire: t.Wire, coeff: t.Coeff})
638		}
639		return out
640	}
641	
642	// ---- strict decoding of a persisted definition ----------------------------
643	//
644	// persistDefinition's decoder is the committed-data endpoint of the shared
645	// schema: a stored definition must have exactly the shape the importer
646	// writes, and every shape failure is data corruption, not a bad request.
647	// This runs while the envelope is being read, before validateEnvelope: a
648	// definition that omits a side array or a term's wire/coeff — which a plain
649	// struct decode would silently turn into a nil slice or a zero int/string —
650	// is refused at read time instead of being mistaken for an empty array, wire
651	// 0 or an empty coefficient. An explicitly empty side array still decodes to
652	// the zero linear combination and an explicit wire:0 still names the
653	// constant wire; both are ordinary values and stay legal. The circuit
654	// record's definition pointer itself may be absent or null: encoding/json
655	// leaves the pointer nil without invoking this method, which is exactly the
656	// legacy counts-only state.
657	//
658	// The decoder enforces shape only. The semantic rules (prime modulus, wire
659	// range, constraint count) are re-checked by validateEnvelope through the
660	// same definitionFromPersist pipeline used after a clean import.
661	func (p *persistDefinition) UnmarshalJSON(raw []byte) error {
662		shape, err := decodeDefinitionShape(raw, storedDefinitionSource)
663		if err != nil {
664			return err
665		}
666		*p = shape.toPersist()
667		return nil
668	}
669

