1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// These tests cover the CLI contract for a non-ASCII lookalike spelling of
11	// the compiled-artifact binding field: "compiled_haſh" (U+017F long s,
12	// written directly or as the JSON escape u017f) is matched onto
13	// compiled_hash by encoding/json's Unicode-folded tag matching, but it is
14	// not an accepted spelling of the binding. A record carrying it — even with
15	// a legal hash or an empty string, and even beside a correctly spelled
16	// compiled_hash — is data corruption: every data command fails at open with
17	// exit code 3, prints no record, names the damaged job and the compiled_hash
18	// field, and leaves data.json byte-for-byte in place.
19	
20	// cliLongS is one literal long-s rune; cliJSONEscape is one literal
21	// backslash, so the escaped spelling keeps its backslash in source.
22	const cliLongS = "ſ"
23	const cliJSONEscape = `\`
24	
25	// rewriteJobFieldCLI replaces the committed j1 binding field with an
26	// arbitrary raw JSON fragment and returns the damaged bytes now on disk.
27	func rewriteJobFieldCLI(t *testing.T, dir, hash, fragment string) []byte {
28		t.Helper()
29		path := filepath.Join(dir, "data.json")
30		raw, err := os.ReadFile(path)
31		if err != nil {
32			t.Fatal(err)
33		}
34		field := `"compiled_hash": "` + hash + `"`
35		if !strings.Contains(string(raw), field) {
36			t.Fatalf("committed file does not carry the bound field %q", field)
37		}
38		bad := []byte(strings.Replace(string(raw), field, fragment, 1))
39		if err := os.WriteFile(path, bad, 0o644); err != nil {
40			t.Fatal(err)
41		}
42		return bad
43	}
44	
45	// TestCLIJobCompiledHashLookalikeExitCode: a long-s spelling of the binding
46	// key, direct or escaped, with null / a legal hash / an empty string as its
47	// value, makes every data command exit 3 without touching the file.
48	func TestCLIJobCompiledHashLookalikeExitCode(t *testing.T) {
49		direct := "compiled_ha" + cliLongS + "h"
50		escaped := "compiled_ha" + cliJSONEscape + "u017f" + "h"
51		cases := []struct {
52			name    string
53			keyText string
54			value   string
55		}{
56			{"direct long s, null", direct, "null"},
57			{"direct long s, legal hash", direct, `"deadbeef"`},
58			{"direct long s, empty string", direct, `""`},
59			{"escaped long s, null", escaped, "null"},
60			{"escaped long s, legal hash", escaped, `"deadbeef"`},
61			{"escaped long s, empty string", escaped, `""`},
62		}
63		for _, tc := range cases {
64			t.Run(tc.name, func(t *testing.T) {
65				dir := filepath.Join(t.TempDir(), "bench")
66				hash := seedBoundJobCLI(t, dir)
67				bad := rewriteJobFieldCLI(t, dir, hash, `"`+tc.keyText+`": `+tc.value)
68	
69				commands := [][]string{
70					{"job-get", "--dir", dir, "--id", "j1"},
71					{"job-list", "--dir", dir},
72					{"job-submit", "--dir", dir, "--id", "j2", "--name", "mul", "--version", "1"},
73					{"circuit-list", "--dir", dir},
74					{"circuit-create", "--dir", dir, "--name", "other", "--version", "1"},
75				}
76				for _, args := range commands {
77					r := callCLI(t, args...)
78					if r.code != 3 {
79						t.Fatalf("%s: want exit 3, got %d (out=%q err=%q)", args[0], r.code, r.out, r.err)
80					}
81					if r.out != "" {
82						t.Fatalf("%s printed a record despite corruption: %q", args[0], r.out)
83					}
84					if !strings.Contains(r.err, "read failed") || !strings.Contains(r.err, "data corrupt") {
85						t.Fatalf("%s: unexpected error text %q", args[0], r.err)
86					}
87				}
88	
89				// The failure names the damaged job and the canonical binding field.
90				r := callCLI(t, "job-get", "--dir", dir, "--id", "j1")
91				if !strings.Contains(r.err, `"j1"`) || !strings.Contains(r.err, "compiled_hash") {
92					t.Fatalf("error does not name the damaged job and field: %q", r.err)
93				}
94	
95				left, err := os.ReadFile(filepath.Join(dir, "data.json"))
96				if err != nil {
97					t.Fatal(err)
98				}
99				if string(left) != string(bad) {
100					t.Fatalf("data.json changed after refused commands")
101				}
102			})
103		}
104	}
105	
106	// TestCLIJobCompiledHashLookalikeBesideCanonical: a long-s spelling together
107	// with a correctly spelled compiled_hash is refused in either key order and
108	// whether the two values agree — even when both carry the real artifact
109	// hash. The CLI never selects one of the values and continues.
110	func TestCLIJobCompiledHashLookalikeBesideCanonical(t *testing.T) {
